"""Assemble a bounded public evidence package and readable project notes."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,html,json,os,shutil
import psycopg
from pipeline import ROOT,env,write_json
env();public=ROOT/'public';downloads=public/'downloads';evidence=public/'evidence';downloads.mkdir(parents=True,exist_ok=True);evidence.mkdir(exist_ok=True)
def read(name):return json.loads((ROOT/'evidence'/name).read_text(encoding='utf-8-sig'))
source=read('source-manifest.json');data=read('data-verification.json');security=read('api-security.json');bench=read('benchmarks.json');host=read('hosted-database.json')
checks={'generated_at':datetime.now(timezone.utc).isoformat(),'release':'0.2.0','data_version':source['data_version'],'data':data,'security':security,'benchmarks':bench['benchmarks'],'benchmark_environment':bench['environment'],'synthetic':bench['synthetic'],'concurrency':bench['concurrency'],'backup_restore':bench['backup_restore'],'hosted_database':host,'limitations':['Historical public data, not a commissioned Olist system.','Local warm-query measurements are not public-site capacity or financial savings.','Synthetic records are isolated from business findings.','Security evidence covers tested paths, not universal immunity.','Free-plan uptime and continued provider allowances are not guaranteed.']}
for filename in ['browser-verification.json','powerbi-desktop.json']:
    if (ROOT/'evidence'/filename).exists():checks[filename.split('.')[0]]=read(filename)
write_json(evidence/'release-checks.json',checks);shutil.copy2(ROOT/'evidence/source-manifest.json',evidence/'source-manifest.json')
style='body{font:15px/1.7 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;color:#232743;max-width:1050px;margin:0 auto;padding:50px 28px;background:#f7f4ee}h1{font-size:36px;letter-spacing:-1px;line-height:1.2}h2{margin-top:35px;font-size:22px}h3{margin-top:25px}p,li{color:#535875}a{color:#334bc4}code{font-size:12px;background:#eef0ff;padding:2px 5px}table{width:100%;border-collapse:collapse;background:#fff;font-size:13px}td,th{padding:10px 14px;border:1px solid #dedbd3;text-align:left}th{background:#e9edff}small{color:#535875}.eyebrow{letter-spacing:2px;font-size:11px;color:#903c29}.note{padding:20px;background:#f3e7df;border-left:3px solid #b54d35}svg{max-width:100%;height:auto}@media print{body{background:#fff;padding:0;font-size:11px}h2{break-after:avoid}table{font-size:10px}tr{break-inside:avoid}}'
(downloads/'document.css').write_text(style)
def doc(name,title,body):
    (downloads/name).write_text('<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><link rel="stylesheet" href="/downloads/document.css"></head><body><div class="eyebrow">COMMERCE OPERATIONS EXPLORER</div><h1>'+title+'</h1>'+body+'<hr><small>Independent project by Bronson Hatch. Implementation, tests, and documentation assisted by Codex. Data: Olist, CC BY-NC-SA 4.0.</small></body></html>')
bench_rows=''.join(f'<tr><td>{html.escape(b["name"])}</td><td>{b["baseline_median_ms"]:.3f} ms</td><td>{b["optimized_median_ms"]:.3f} ms</td><td>Identical results</td></tr>' for b in bench['benchmarks'])
doc('case-study.html','Commerce analysis, with an inspectable database',f'''<p>By Bronson Hatch · independent project · release 0.2.0</p><p class="note">Explore historical commerce activity through a working PostgreSQL application and a separate Power BI analytical model. The business interface answers questions about orders, merchandise, sellers, and deliveries; engineering details remain available for inspection.</p><h2>Business problem</h2><p>Commerce records live at different grains. An order can have several items, payment records, and reviews. Joining all of them directly can inflate money totals and misstate delivery or review rates. This project organizes those records into a relational core and a reporting model with explicit definitions.</p><h2>What the application does</h2><p>Filter by purchase period and customer region. Inspect order items and payments without multiplying records. Compare seller/category merchandise value and regional delivery outcomes. Open a query panel to inspect the actual SQL template and separately bound parameters.</p><h2>Data and correctness</h2><p>The complete source contains 99,441 orders. Delivered merchandise value is R$13,221,498.11, independently reconstructed from original CSV prices using decimal arithmetic. The source has 814 repeated review IDs; the model retains separate source records and applies a deterministic latest-review rule. Review text stays outside the public application views.</p><p>Checks cover source totals, 150 seeded per-order calculations, filtered totals, delivery eligibility, fact-table grains, permission restrictions and rollback after a constraint failure. Merchandise value excludes freight and does not represent platform revenue or profit.</p><h2>Architecture</h2><p>Original files → preserved raw records → typed relational tables → order, order-item and payment facts → restricted API views → React application and Power BI. Foreign keys and appropriate exact-decimal fields enforce the model. Runtime credentials only permit approved reads.</p><h2>Measured SQL performance</h2><p>Each comparison uses a valid restored baseline, five warm-ups and 50 measured executions. Baseline/optimized execution order alternates, and results must match. Values below are local warm-query elapsed times, including local client communication.</p><table><tr><th>Workload</th><th>Baseline median</th><th>Optimized median</th><th>Correctness</th></tr>{bench_rows}</table><p>The separate synthetic one-million-order customer-history test improved from {bench['synthetic']['baseline_median_ms']:.3f} to {bench['synthetic']['indexed_median_ms']:.3f} ms median. These generated records are not Olist business findings or a claim about public hosting capacity. Raw samples, plans, index storage and summary-refresh cost are included in the evidence.</p><h2>Security and operations</h2><p>Parameterized queries, structural allowlists, limited permissions, bounded requests, safe text rendering and browser security headers form the application controls. Injection attempts are checked against real query paths. A restored prepared-data backup must reconcile to source totals. Test coverage is described in the evidence; no universal security guarantee is made.</p><h2>Limitations</h2><p>Historical records cover 2016–2018, with incomplete edge months and missing attributes. Original timestamps do not establish a timezone. Delivery/review comparisons are descriptive. The project is independent and was not commissioned by Olist. Free hosting can sleep or hit quotas, and recorded benchmarks depend on their documented environment.</p><h2>Inspect and reproduce</h2><p><a href="/evidence/release-checks.json">Verification and performance evidence</a> · <a href="/downloads/data-dictionary.html">Data dictionary</a> · <a href="/evidence/source-manifest.json">Source manifest</a></p>''')
with psycopg.connect(os.environ['OWNER_DATABASE_URL']) as c:
    tables=c.execute("SELECT table_schema,table_name FROM information_schema.tables WHERE table_schema IN ('core','analytics') AND table_type='BASE TABLE' ORDER BY table_schema,table_name").fetchall();body='<p>Source: <a href="https://www.kaggle.com/datasets/olistbr/brazilian-ecommerce">Olist Brazilian E-Commerce Public Dataset</a>. Currency: BRL. Timestamps retain source wall-clock values.</p><h2>Metrics and eligibility</h2><ul><li>Delivered merchandise value: item prices for delivered orders, excluding freight.</li><li>Average order value: delivered merchandise value divided by delivered-order count.</li><li>Late delivery: actual calendar date after estimated calendar date; denominator excludes missing dates and undelivered orders.</li><li>Latest review: answer timestamp, then creation timestamp, then source-row key, in descending order.</li><li>Period filters always refer to purchase date. Geography belongs to the order destination, not an assumed permanent customer address.</li></ul><h2>Actual table definitions</h2>'
    for schema,table in tables:
        columns=c.execute('SELECT column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema=%s AND table_name=%s ORDER BY ordinal_position',(schema,table)).fetchall();constraints=c.execute("SELECT conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid=%s::regclass ORDER BY conname",(schema+'.'+table,)).fetchall();body+=f'<h3>{schema}.{table}</h3><table><tr><th>Column</th><th>Type</th><th>Nullable</th></tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in columns)+'</table><p>'+ '<br>'.join(html.escape(defn) for _,defn in constraints)+'</p>'
doc('data-dictionary.html','Data dictionary and business definitions',body)
print('Public evidence, case study and actual-schema dictionary generated.')
